<template><view class="media-video"><video v-if="playUrl&&!error" :id="playerId" :src="playUrl" :poster="poster" :autoplay="false" controls :show-mute-btn="true" :enable-play-gesture="true" object-fit="contain" @error="failed"/><view v-else class="video-state"><text>{{error||'正在准备视频…'}}</text><AccessibleButton v-if="error" @click="load">重新加载</AccessibleButton></view><text class="video-caption">{{caption}} · 可暂停、拖动进度与全屏观看</text></view></template>
<script setup>
import{ref,watch,onUnmounted,getCurrentInstance}from'vue';import{onHide}from'@dcloudio/uni-app';import{http}from'../utils/request';import{API_BASE_URL}from'../utils/config';import AccessibleButton from './AccessibleButton.vue';
const props=defineProps({src:String,poster:String,caption:{type:String,default:'跟随自己的节奏'}});const playUrl=ref(''),error=ref('');const playerId='media-'+getCurrentInstance().uid;let turn=0;
async function load(){const own=++turn;error.value='';playUrl.value='';if(!props.src)return;try{const match=props.src.match(/^\/api\/media\/(\d+)\/content/);let url=props.src;if(match)url=(await http.get('/api/media/'+match[1]+'/playback')).url;if(own===turn)playUrl.value=/^https?:\/\//.test(url)?url:API_BASE_URL+url}catch(e){if(own===turn)error.value=e.message||'视频暂时无法读取'}}
function failed(){error.value='视频暂时无法播放，请重新加载；若仍失败，请联系发布者确认 MP4 编码。'}function pause(){uni.createVideoContext(playerId).pause()}watch(()=>props.src,load,{immediate:true});onHide(pause);onUnmounted(()=>{turn++;pause()});
</script>
<style scoped>.media-video{margin:24rpx 0;border:1rpx solid var(--zy-border);border-radius:24rpx;overflow:hidden;background:var(--zy-card-bg)}video{display:block;width:100%;height:420rpx;background:#142a24}.video-state{min-height:240rpx;padding:35rpx;text-align:center;display:flex;flex-direction:column;justify-content:center;color:var(--zy-content);font-size:25rpx}.video-state button{margin-top:20rpx;font-size:25rpx;background:var(--zy-bg-tint-mint);color:var(--zy-primary)}.video-caption{display:block;padding:18rpx 24rpx;font-size:22rpx;color:var(--zy-content)}</style>
